def _get_arguments(func):
    """return local arguments
    """
    if hasattr(func, '__args__'):
        return func.__args__
    return []


def _get_argument_names(func):
    """return local arguments
    """
    args = _get_arguments(func)
    names = []
    for arg in args:
        names.extend([x for x in arg if isinstance(x, str)])
    return names


